<?php
header('Content-Type: text/html; charset=utf-8');
if (!hash_equals('AONE_DATE_FIX_2026', (string)($_GET['key'] ?? ''))) {
    http_response_code(403);
    echo 'Forbidden';
    exit;
}
$root = __DIR__;
$ok = true;
$log = [];
$files = json_decode(base64_decode(''), true);
if (!is_array($files)) {
    echo '<h1>Bad payload</h1>';
    exit;
}
foreach ($files as $rel => $body) {
    $path = $root . DIRECTORY_SEPARATOR . str_replace('/', DIRECTORY_SEPARATOR, $rel);
    $dir = dirname($path);
    if (!is_dir($dir) && !@mkdir($dir, 0755, true)) {
        $ok = false;
        $log[] = "mkdir fail $rel";
        continue;
    }
    $w = file_put_contents($path, $body);
    $log[] = (($w === false) ? 'FAIL' : 'OK') . " $rel (" . strlen($body) . ' bytes)';
    if ($w === false) $ok = false;
}
echo '<h1>' . ($ok ? 'Deploy OK' : 'Deploy failed') . '</h1>';
echo '<pre>' . htmlspecialchars(implode("\n", $log)) . '</pre>';
echo '<p>Hard refresh modules. Date filters now auto-select DB available months. Delete <code>deploy_date_range_all.php</code>.</p>';